//! The CQL catalogs, compiled in and parsed once per process.
//!
//! `catalogs/cql/` is generated by `scripts/sync_cql_catalog.py` from
//! CrowdStrike's CQL function reference (facts only: names, parameters, types,
//! defaults, allowed values, bounds, lifecycle) and from redistributable sources
//! of Falcon event and field names. `docs` strings are written for this catalog.
//! LogScale is schemaless, so fields are hover and completion data, never a
//! reason for a finding.

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const FUNCTIONS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/cql/functions.toml"
));
const EVENTS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/cql/events.toml"
));
const FIELDS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/catalogs/cql/fields.toml"
));

/// One CQL function (`groupBy`, `array:filter`, `ioc:lookup`).
#[derive(Debug, Clone, Deserialize)]
pub struct Function {
    pub name: String,
    #[serde(default)]
    pub aliases: Vec<String>,
    #[serde(default)]
    pub category: Vec<String>,
    #[serde(default)]
    pub kind: Vec<String>,
    pub aggregate: bool,
    pub signature: Option<String>,
    pub docs: String,
    pub citation: String,
    #[serde(default)]
    pub contexts: Vec<String>,
    #[serde(default)]
    pub incompatible: Vec<String>,
    pub since: Option<String>,
    #[serde(default)]
    pub deprecated: bool,
    pub deprecated_note: Option<String>,
    #[serde(default)]
    pub removed: bool,
    pub removed_in: Option<String>,
    pub replacement: Option<String>,
    #[serde(default)]
    pub experimental: bool,
    pub feature_flag: Option<String>,
    #[serde(default)]
    pub ngsiem: bool,
    /// `false` only for a Next-Gen SIEM-only function (`remoteTable`).
    pub logscale: Option<bool>,
    #[serde(default)]
    pub unavailable: bool,
    #[serde(default)]
    pub parameters: Vec<Parameter>,
}

/// One parameter of a CQL function.
#[derive(Debug, Clone, Deserialize)]
pub struct Parameter {
    pub name: String,
    /// The catalog's type vocabulary (`field`, `string`, `integer`, `enum`, ...).
    #[serde(rename = "type")]
    pub ty: String,
    pub required: bool,
    /// The parameter whose name may be left out (at most one per function).
    pub unnamed: bool,
    /// Accepts an array `[a, b]`.
    pub multi: bool,
    /// Takes a `{ ... }` subquery or a function call.
    pub query: bool,
    pub default: Option<String>,
    #[serde(default)]
    pub values: Vec<String>,
    /// `values` are keywords and any number is also valid (`limit=max`).
    #[serde(default)]
    pub values_open: bool,
    #[serde(default)]
    pub deprecated_values: Vec<String>,
    pub min: Option<i64>,
    pub max: Option<i64>,
    #[serde(default)]
    pub aliases: Vec<String>,
    #[serde(default)]
    pub deprecated: bool,
    pub deprecated_since: Option<String>,
}

impl Parameter {
    /// Whether `name` (case-insensitive) names this parameter or an alias.
    pub fn answers_to(&self, name: &str) -> bool {
        self.name.eq_ignore_ascii_case(name)
            || self.aliases.iter().any(|a| a.eq_ignore_ascii_case(name))
    }
}

impl Function {
    pub fn parameter(&self, name: &str) -> Option<&Parameter> {
        self.parameters.iter().find(|p| p.answers_to(name))
    }

    /// The parameter an argument without a name binds.
    pub fn unnamed_parameter(&self) -> Option<&Parameter> {
        self.parameters.iter().find(|p| p.unnamed)
    }

    /// `name(param, [optional])`, from the catalog or built from the parameters.
    pub fn signature(&self) -> String {
        if let Some(s) = &self.signature {
            return s.clone();
        }
        let params: Vec<String> = self
            .parameters
            .iter()
            .filter(|p| !p.deprecated)
            .map(|p| {
                if p.required {
                    p.name.clone()
                } else {
                    format!("[{}]", p.name)
                }
            })
            .collect();
        format!("{}({})", self.name, params.join(", "))
    }

    /// Accepted where an event stream is searched (not parser-only).
    pub fn in_queries(&self) -> bool {
        self.removed || self.contexts.is_empty() || self.contexts.iter().any(|c| c == "query")
    }
}

/// A Falcon sensor event (`#event_simpleName` value).
#[derive(Debug, Clone, Deserialize)]
pub struct Event {
    pub name: String,
    pub category: Option<String>,
    #[serde(default)]
    pub platforms: Vec<String>,
    #[serde(default)]
    pub fields: Vec<String>,
    #[serde(default)]
    pub sources: Vec<String>,
    #[serde(default)]
    pub mentions: i64,
}

/// A LogScale built-in, Falcon, or CPS (ECS-based) field or tag.
#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    pub name: String,
    /// `logscale`, `falcon` or `cps`.
    pub layer: String,
    /// `metadata` (`@...`), `tag` (`#...`), `field` or `namespace`.
    pub kind: String,
    #[serde(rename = "type")]
    pub ty: String,
    pub scope: Option<String>,
    pub docs: Option<String>,
    #[serde(default)]
    pub ecs: bool,
    #[serde(default)]
    pub values: Vec<String>,
    #[serde(default)]
    pub sources: Vec<String>,
}

#[derive(Deserialize)]
struct FunctionsFile {
    functions: Vec<Function>,
}

#[derive(Deserialize)]
struct EventsFile {
    #[serde(default)]
    platforms: Vec<String>,
    #[serde(default)]
    common_fields: Vec<String>,
    events: Vec<Event>,
}

#[derive(Deserialize)]
struct FieldsFile {
    fields: Vec<Field>,
}

/// Every CQL catalog, indexed.
#[derive(Debug)]
pub struct Catalog {
    pub functions: Vec<Function>,
    pub events: Vec<Event>,
    pub fields: Vec<Field>,
    /// The confirmed `event_platform` values.
    pub platforms: Vec<String>,
    /// Fields on (nearly) every sensor event.
    pub common_fields: Vec<String>,
    by_function: HashMap<String, usize>,
    by_event: HashMap<String, usize>,
    by_field: HashMap<String, usize>,
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let functions: FunctionsFile =
                toml::from_str(FUNCTIONS_TOML).expect("catalogs/cql/functions.toml");
            let events: EventsFile = toml::from_str(EVENTS_TOML).expect("catalogs/cql/events.toml");
            let fields: FieldsFile = toml::from_str(FIELDS_TOML).expect("catalogs/cql/fields.toml");
            let mut by_function = HashMap::new();
            for (i, f) in functions.functions.iter().enumerate() {
                by_function.insert(f.name.to_ascii_lowercase(), i);
                for alias in &f.aliases {
                    by_function.insert(alias.to_ascii_lowercase(), i);
                }
            }
            let by_event = events
                .events
                .iter()
                .enumerate()
                .map(|(i, e)| (e.name.clone(), i))
                .collect();
            let by_field = fields
                .fields
                .iter()
                .enumerate()
                .map(|(i, f)| (f.name.clone(), i))
                .collect();
            Catalog {
                functions: functions.functions,
                events: events.events,
                fields: fields.fields,
                platforms: events.platforms,
                common_fields: events.common_fields,
                by_function,
                by_event,
                by_field,
            }
        })
    }

    /// A function by name, without regard to case (CQL resolves them so).
    pub fn function(&self, name: &str) -> Option<&Function> {
        self.by_function
            .get(&name.to_ascii_lowercase())
            .map(|&i| &self.functions[i])
    }

    /// An event by its exact name.
    pub fn event(&self, name: &str) -> Option<&Event> {
        self.by_event.get(name).map(|&i| &self.events[i])
    }

    /// A field or tag by its exact name; `Vendor.x` resolves to the `Vendor` namespace.
    pub fn field(&self, name: &str) -> Option<&Field> {
        if let Some(&i) = self.by_field.get(name) {
            return Some(&self.fields[i]);
        }
        let (head, _) = name.split_once('.')?;
        self.by_field
            .get(head)
            .map(|&i| &self.fields[i])
            .filter(|f| f.kind == "namespace")
    }

    pub fn suggest_function(&self, name: &str) -> Option<&str> {
        closest(
            self.functions
                .iter()
                .filter(|f| !f.removed && !f.unavailable)
                .map(|f| f.name.as_str()),
            name,
            2,
        )
    }

    /// An event whose name differs only in case, else one within two edits.
    pub fn suggest_event(&self, name: &str) -> Option<&str> {
        if let Some(e) = self
            .events
            .iter()
            .find(|e| e.name.eq_ignore_ascii_case(name))
        {
            return Some(e.name.as_str());
        }
        closest(self.events.iter().map(|e| e.name.as_str()), name, 2)
    }

    pub fn suggest_parameter<'f>(&self, function: &'f Function, name: &str) -> Option<&'f str> {
        closest(function.parameters.iter().map(|p| p.name.as_str()), name, 2)
    }
}

/// The candidate nearest to `target` (case-insensitive), within `max` edits.
pub(crate) fn closest<'a>(
    names: impl Iterator<Item = &'a str>,
    target: &str,
    max: usize,
) -> Option<&'a str> {
    let target = target.to_ascii_lowercase();
    names
        .map(|n| (n, edit_distance(&n.to_ascii_lowercase(), &target)))
        .filter(|(_, d)| *d > 0 && *d <= max)
        .min_by_key(|(_, d)| *d)
        .map(|(n, _)| n)
}

fn edit_distance(a: &str, b: &str) -> usize {
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.chars().enumerate() {
        let mut cur = vec![i + 1; b.len() + 1];
        for (j, cb) in b.iter().enumerate() {
            let cost = usize::from(ca != *cb);
            cur[j + 1] = (prev[j] + cost).min(prev[j + 1] + 1).min(cur[j] + 1);
        }
        prev = cur;
    }
    prev[b.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogs_load_and_index() {
        let c = Catalog::cached();
        assert!(c.functions.len() >= 190, "{}", c.functions.len());
        let g = c.function("groupby").expect("case-insensitive lookup");
        assert_eq!(g.name, "groupBy");
        assert!(g.aggregate);
        assert_eq!(
            g.unnamed_parameter().map(|p| p.name.as_str()),
            Some("field")
        );
        assert!(c.function("array:contains").is_some());
        assert!(c.function("rdns").is_some_and(|f| f.removed));
        assert!(c.event("ProcessRollup2").is_some());
        assert!(c.field("@timestamp").is_some());
        assert!(c.field("#event_simpleName").is_some());
    }

    #[test]
    fn at_most_one_unnamed_parameter() {
        for f in &Catalog::cached().functions {
            let n = f.parameters.iter().filter(|p| p.unnamed).count();
            assert!(n <= 1, "{} has {n} unnamed parameters", f.name);
        }
    }

    #[test]
    fn suggestions() {
        let c = Catalog::cached();
        assert_eq!(c.suggest_function("groupBi"), Some("groupBy"));
        assert_eq!(c.suggest_function("groupBy"), None);
        assert_eq!(c.suggest_event("processrollup2"), Some("ProcessRollup2"));
    }
}
